        private void ConfigureLayout()
        {
            var content = HotelTheme.Page(this);
            HotelTheme.Title(label1, "Quản lý phòng");
            HotelTheme.Action(btnAddRoom, "Thêm phòng");
            HotelTheme.Grid(DataGridView1);

            var listTitle = HotelTheme.Label("Danh sách phòng", HotelTheme.Section, HotelTheme.Ink);
            var formTitle = HotelTheme.Label("Phòng mới", HotelTheme.Section, HotelTheme.Ink);
            var list = HotelTheme.Card(content, listTitle, DataGridView1);
            var form = HotelTheme.Card(content, formTitle, label2, txtRoomNo, label3, txtRoomType,
                label5, txtBed, label4, txtPrice, btnAddRoom);

            void Arrange()
            {
                int P(int value) => HotelTheme.Px(this, value);
                bool SideBySide(int width) => width >= P(900);
                HotelTheme.FitPage(this, content, 420, width => SideBySide(width) ? 578 : 830);
                int gutter = Math.Max(P(28), (content.Width - P(1400)) / 2);
                int available = content.Width - gutter * 2;
                bool wide = SideBySide(content.Width);
                int formWidth = wide ? Math.Min(P(365), available / 3) : available;
                int listHeight = wide ? content.Height - P(102) : P(285);
                int listWidth = wide ? available - formWidth - P(20) : available;

                label1.Location = new Point(gutter, P(24));
                list.SetBounds(gutter, P(76), listWidth, listHeight);
                form.SetBounds(wide ? list.Right + P(20) : gutter,
                    wide ? P(76) : list.Bottom + P(16), formWidth, P(426));
                listTitle.Location = new Point(P(18), P(15));
                DataGridView1.SetBounds(P(18), P(54), listWidth - P(36), listHeight - P(72));
                formTitle.Location = new Point(P(20), P(15));
                int fieldWidth = formWidth - P(40);
                HotelTheme.PlaceField(txtRoomNo, label2, P(20), P(55), fieldWidth);
                HotelTheme.PlaceField(txtRoomType, label3, P(20), P(129), fieldWidth);
                HotelTheme.PlaceField(txtBed, label5, P(20), P(203), fieldWidth);
                HotelTheme.PlaceField(txtPrice, label4, P(20), P(277), fieldWidth);
                btnAddRoom.SetBounds(P(20), P(361), fieldWidth, P(44));
            }

            Resize += (sender, args) => Arrange();
            HandleCreated += (sender, args) => Arrange();
            Arrange();
        }

